package com.chatsystem.user.controller.social;import com.chatsystem.shared.model.UserAccount;import com.chatsystem.shared.service.SocialService;import com.chatsystem.user.navigation.*;import com.chatsystem.user.ui.cell.BlockedUserCell;import javafx.fxml.FXML;import javafx.scene.control.*;
public final class BlockedUsersController{private final SocialService social;private final UserNavigator nav;@FXML private ListView<UserAccount> blockedList;@FXML private Label blockedFeedbackLabel;public BlockedUsersController(SocialService s,UserNavigator n){social=s;nav=n;}@FXML private void initialize(){blockedList.setItems(social.getBlockedUsers());blockedList.setCellFactory(x->new BlockedUserCell());}@FXML private void unblock(){var u=blockedList.getSelectionModel().getSelectedItem();if(u==null){blockedFeedbackLabel.setText("Choose a blocked user");return;}var r=social.unblockUser(u.getId());blockedFeedbackLabel.setText(r.isSuccess()?"User unblocked":r.errors().get(0).message());}@FXML private void back(){nav.navigate(ViewRequest.of(UserRoute.FRIENDS));}}
